  for (const [ia, ib] of cubeEdges) {
    const a = cubeVertices[ia], b = cubeVertices[ib];
    const fa = normal.dot(a) - constant;
    const fb = normal.dot(b) - constant;
    if (Math.abs(fa) < 1e-7) uniquePush(pts, a);
    if (Math.abs(fb) < 1e-7) uniquePush(pts, b);
    if (fa * fb < -1e-10) {
      const t = fa / (fa - fb);
      uniquePush(pts, new THREE.Vector3().lerpVectors(a, b, t));
    }
  }
  if (pts.length < 3) return [];
  const centroid = pts.reduce((s, p) => s.add(p), new THREE.Vector3()).multiplyScalar(1 / pts.length);
  const n = normal.clone().normalize();
  const ref = Math.abs(n.dot(new THREE.Vector3(0, 1, 0))) < 0.92 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0);
  const u = new THREE.Vector3().crossVectors(ref, n).normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  pts.sort((p, q) => {
    const dp = new THREE.Vector3().subVectors(p, centroid);
    const dq = new THREE.Vector3().subVectors(q, centroid);
    return Math.atan2(dp.dot(v), dp.dot(u)) - Math.atan2(dq.dot(v), dq.dot(u));
  });
  return pts;
}

function makePlaneMesh(poly, mat) {
  if (poly.length < 3) return null;
  const center = poly.reduce((s, p) => s.add(p), new THREE.Vector3()).multiplyScalar(1 / poly.length);
  const positions = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i];
    const b = poly[(i + 1) % poly.length];
    for (const p of [center, a, b]) {
      const w = latticeToWorld(p.x, p.y, p.z);
      positions.push(w.x, w.y, w.z);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 2;
  return mesh;
}

function makeDashedOutline(poly) {
  if (poly.length < 3) return null;
  const positions = [];
  for (let i = 0; i < poly.length; i++) {
    const a = latticeToWorld(poly[i].x, poly[i].y, poly[i].z);
    const b = latticeToWorld(poly[(i + 1) % poly.length].x, poly[(i + 1) % poly.length].y, poly[(i + 1) % poly.length].z);
    positions.push(a.x, a.y, a.z, b.x, b.y, b.z);
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  const line = new THREE.LineSegments(geom, dashMat);
  line.computeLineDistances();
  line.renderOrder = 3;
  return line;
}

function addDoubleArrow(parent, start, end) {
  const s = latticeToWorld(start.x, start.y, start.z);
  const e = latticeToWorld(end.x, end.y, end.z);
  const dir = new THREE.Vector3().subVectors(e, s);
  const len = dir.length();
  if (len < 0.05) return;
  dir.normalize();
  const headH = 0.115;
  const shaftStart = s.clone().addScaledVector(dir, headH * 0.55);
  const shaftEnd = e.clone().addScaledVector(dir, -headH * 0.55);
  parent.add(cylinderBetween(shaftStart, shaftEnd, 0.016, arrowMat, 10));

  const headGeom = new THREE.ConeGeometry(0.05, headH, 18);
  const h1 = new THREE.Mesh(headGeom, arrowMat);
  h1.position.copy(e);
  h1.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  parent.add(h1);

  const h0 = new THREE.Mesh(headGeom, arrowMat);
  h0.position.copy(s);
  h0.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().negate());
  parent.add(h0);
}

function activePlaneData() {
  const family = uiPlaneFamily.value;
  const idx = Number(uiPlaneIndex.value);
  if (family.includes('100')) {
    const z0 = idx - 1;
    const sign = z0 < 3 ? 1 : -1;
    return {
      family,
      idx,
      normal: new THREE.Vector3(0, 0, 1),
      constant: z0,
      adjConstant: z0 + sign,
      unitNormal: new THREE.Vector3(0, 0, sign),
      spacing: 1,
      label: 'd<sub>100</sub> = a',
      familyLabel: '{100}',
      arrowStart: new THREE.Vector3(3.28, 2.55, z0),
      arrowEnd: new THREE.Vector3(3.28, 2.55, z0 + sign),
      labelPos: new THREE.Vector3(3.55, 2.78, z0 + sign * 0.5),
      familyPos: new THREE.Vector3(1.5, 3.32, z0)
    };
  }
  const c = idx - 2;
  const sign = c < 2 ? 1 : -1;
  const normal = new THREE.Vector3(1, 0, -1);
  const unit = normal.clone().normalize().multiplyScalar(sign);
  const zBase = Math.min(2.35, Math.max(0.65, 1.45 - c * 0.2));
  const xBase = Math.min(2.35, Math.max(0.65, c + zBase));
  const start = new THREE.Vector3(xBase, 3.22, zBase);
  const end = start.clone().add(unit.clone().multiplyScalar(1 / Math.sqrt(2)));
  return {
    family,
    idx,
    normal,
    constant: c,
    adjConstant: c + sign,
    unitNormal: unit,
    spacing: 1 / Math.sqrt(2),
    label: 'd<sub>110</sub> = a/√2',
    familyLabel: '{110}',
    arrowStart: start,
    arrowEnd: end,
    labelPos: start.clone().lerp(end, 0.5).add(new THREE.Vector3(0.2, 0.22, 0)),
    familyPos: new THREE.Vector3(1.5, 3.38, 1.5)
  };
}

function setAtomHighlights(data) {
  const haloGeom = new THREE.SphereGeometry(0.122, 18, 12);
  for (const atom of atomMeshes) {
    const p = atom.userData.lattice;
    const val = data.normal.dot(new THREE.Vector3(p.x, p.y, p.z)) - data.constant;
    const onPlane = Math.abs(val) <= 0.02;
    atom.material = onPlane ? atomHighlightMat : atomBaseMat;
    if (onPlane) {
      const halo = new THREE.Mesh(haloGeom, haloMat);
      halo.position.copy(atom.position);
      dynamicGroup.add(halo);
    }
  }
}

function updateLabels(data) {
  if (spacingLabel) {
    spacingLabel.div.innerHTML = data.label;
    spacingLabel.pos.copy(latticeToWorld(data.labelPos.x, data.labelPos.y, data.labelPos.z));
  }
  if (familyLabel) {
    familyLabel.div.innerHTML = data.familyLabel + ' plane family';
    familyLabel.pos.copy(latticeToWorld(data.familyPos.x, data.familyPos.y, data.familyPos.z));
  }
}

function rebuildPlane() {
  scene.remove(dynamicGroup);
  dynamicGroup.traverse(o => {
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
  });
  dynamicGroup = new THREE.Group();
  scene.add(dynamicGroup);

  uiPlaneIndexValue.textContent = uiPlaneIndex.value;
  const data = activePlaneData();

  const activePoly = clippedPlanePolygon(data.normal, data.constant);
  const adjPoly = clippedPlanePolygon(data.normal, data.adjConstant);
  const activeMesh = makePlaneMesh(activePoly, planeMat);
  if (activeMesh) dynamicGroup.add(activeMesh);

  if (activePoly.length >= 4) {
    const topPoly = activePoly.map(p => p.clone()).filter(p => p.y >= 1.5);
    if (topPoly.length >= 3) {
      const topMesh = makePlaneMesh(topPoly, planeTopMat);
      if (topMesh) dynamicGroup.add(topMesh);
    }
  }

  const outline = makeDashedOutline(adjPoly);
  if (outline) dynamicGroup.add(outline);

  addDoubleArrow(dynamicGroup, data.arrowStart, data.arrowEnd);
  setAtomHighlights(data);
  updateLabels(data);
}

rebuildPlane();
setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 45,
  depthScale: 0.5,
  rollDeg: 0,
  heightFraction: 0.72
});

spacingLabel = addLabel('', new THREE.Vector3(), {
  fontSize: '14px',
  bold: true,
  color: '#14555a',
  background: 'rgba(255,255,255,0.78)'
});
familyLabel = addLabel('', new THREE.Vector3(), {
  fontSize: '14px',
  bold: true,
  color: '#14555a',
  background: 'rgba(255,255,255,0.72)'
});
rebuildPlane();

const demoSteps = [
  {
    title: 'Face-parallel plane',
    narration: 'The highlighted {100} plane is parallel to the front and back cube faces. It passes through a complete square sheet of atoms inside the same cubic lattice.',
    state: { planeFamily: '{100} face-parallel', planeIndex: 2 }
  },
  {
    title: 'Adjacent face-parallel plane',
    narration: 'Moving the index shifts the teal sheet to the next parallel layer of atoms. The orientation stays fixed and the spacing label remains d100 = a.',
    state: { planeFamily: '{100} face-parallel', planeIndex: 3 }
  },
  {
    title: 'Diagonal plane family',
    narration: 'Switching to {110} keeps the same red-sphere lattice but tilts the teal plane diagonally through it, matching the right-hand panel of the source figure.',
    state: { planeFamily: '{110} diagonal', planeIndex: 2 }
  },
  {
    title: 'Adjacent diagonal plane',
    narration: 'The next diagonal sheet is parallel to the first but closer than the face-parallel planes. The spacing label changes to d110 = a/√2.',
    state: { planeFamily: '{110} diagonal', planeIndex: 3 }
  }
];

let currentStep = 0;
let playTimer = null;

function goToStep(i) {
  currentStep = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  uiPlaneFamily.value = step.state.planeFamily;
  uiPlaneIndex.value = step.state.planeIndex;
  uiStepTitle.textContent = step.title;
  uiStepNarration.textContent = step.narration;
  rebuildPlane();
}
window.goToStep = goToStep;

uiPlaneFamily.addEventListener('change', () => {
  clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playDemo').textContent = 'Play';
  rebuildPlane();
});
uiPlaneIndex.addEventListener('input', () => {
  clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playDemo').textContent = 'Play';
  rebuildPlane();
});

document.getElementById('prevStep').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(currentStep + 1));
document.getElementById('playDemo').addEventListener('click', (e) => {
  if (playTimer) {
    clearInterval(playTimer);
    playTimer = null;
    e.currentTarget.textContent = 'Play';
    return;
  }
  e.currentTarget.textContent = 'Pause';
  goToStep(currentStep);
  playTimer = setInterval(() => goToStep(currentStep + 1), 2300);
});

goToStep(0);
