  const geom = new THREE.CylinderGeometry(radius, radius, len, radialSegments);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.copy(p0).add(p1).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

const cubeVertices = [
  new THREE.Vector3(0, 0, 0), new THREE.Vector3(3, 0, 0),
  new THREE.Vector3(3, 3, 0), new THREE.Vector3(0, 3, 0),
  new THREE.Vector3(0, 0, 3), new THREE.Vector3(3, 0, 3),
  new THREE.Vector3(3, 3, 3), new THREE.Vector3(0, 3, 3)
];
const cubeEdges = [
  [0, 1], [1, 2], [2, 3], [3, 0],
  [4, 5], [5, 6], [6, 7], [7, 4],
  [0, 4], [1, 5], [2, 6], [3, 7]
];

function uniquePush(points, p) {
  for (const q of points) if (q.distanceToSquared(p) < 1e-8) return;
  points.push(p.clone());
}

function clippedPlanePolygon(normal, constant) {
  const pts = [];
  for (const [ia, ib] of cubeEdges) {
    const a = cubeVertices[ia], b = cubeVertices[ib];
    const fa = normal.dot(a) - constant;
    const fb = normal.dot(b) - constant;
    if (Math.abs(fa) < 1e-7) uniquePush(pts, a);
    if (Math.abs(fb) < 1e-7) uniquePush(pts, b);
    if (fa * fb < -1e-10) {
      const t = fa / (fa - fb);
      uniquePush(pts, new THREE.Vector3().lerpVectors(a, b, t));
    }
  }
  if (pts.length < 3) return [];
  const centroid = pts.reduce((sum, p) => sum.add(p), new THREE.Vector3()).multiplyScalar(1 / pts.length);
  const n = normal.clone().normalize();
  const ref = Math.abs(n.dot(new THREE.Vector3(0, 1, 0))) < 0.92 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0);
  const u = new THREE.Vector3().crossVectors(ref, n).normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  pts.sort((p, q) => {
    const dp = new THREE.Vector3().subVectors(p, centroid);
    const dq = new THREE.Vector3().subVectors(q, centroid);
    return Math.atan2(dp.dot(v), dp.dot(u)) - Math.atan2(dq.dot(v), dq.dot(u));
  });
  return pts;
}

function makePlaneMesh(poly, material) {
  if (poly.length < 3) return null;
  const center = poly.reduce((sum, p) => sum.add(p), new THREE.Vector3()).multiplyScalar(1 / poly.length);
  const positions = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    for (const p of [center, a, b]) {
      const lp = localPoint(p.x, p.y, p.z);
      positions.push(lp.x, lp.y, lp.z);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, material);
  mesh.renderOrder = 1;
  return mesh;
}

function clearGroup(g) {
  while (g.children.length) {
    const o = g.children.pop();
    o.traverse?.(x => {
      x.geometry?.dispose?.();
      if (Array.isArray(x.material)) x.material.forEach(m => m.dispose?.());
    });
  }
}

function makeArrow(parent, aLat, bLat) {
  const a = localPoint(aLat.x, aLat.y, aLat.z);
  const b = localPoint(bLat.x, bLat.y, bLat.z);
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 0.04) return;
  dir.normalize();
  const headH = 0.055;
  const shaftA = a.clone().addScaledVector(dir, headH * 0.5);
  const shaftB = b.clone().addScaledVector(dir, -headH * 0.5);
  parent.add(cylinderBetween(shaftA, shaftB, 0.009, arrowMat, 10));
  const headGeom = new THREE.ConeGeometry(0.026, headH, 18);
  const h0 = new THREE.Mesh(headGeom, arrowMat);
  h0.position.copy(a);
  h0.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().negate());
  parent.add(h0);
  const h1 = new THREE.Mesh(headGeom, arrowMat);
  h1.position.copy(b);
  h1.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  parent.add(h1);
}

function buildPanel(kind, origin) {
  const root = new THREE.Group();
  root.position.copy(origin);
  scene.add(root);

  const planes = new THREE.Group();
  const rods = new THREE.Group();
  const atoms = new THREE.Group();
  const overlay = new THREE.Group();
  root.add(planes, rods, atoms, overlay);

  const atomGeom = new THREE.SphereGeometry(0.055, 28, 18);
  const atomMeshes = [];

  for (let y = 0; y <= 3; y++) {
    for (let z = 0; z <= 3; z++) {
      for (let x = 0; x < 3; x++) rods.add(cylinderBetween(localPoint(x, y, z), localPoint(x + 1, y, z), 0.0085, rodMat));
    }
  }
  for (let x = 0; x <= 3; x++) {
    for (let z = 0; z <= 3; z++) {
      for (let y = 0; y < 3; y++) rods.add(cylinderBetween(localPoint(x, y, z), localPoint(x, y + 1, z), 0.0085, rodMat));
    }
  }
  for (let x = 0; x <= 3; x++) {
    for (let y = 0; y <= 3; y++) {
      for (let z = 0; z < 3; z++) rods.add(cylinderBetween(localPoint(x, y, z), localPoint(x, y, z + 1), 0.0085, rodMat));
    }
  }

  for (let x = 0; x <= 3; x++) {
    for (let y = 0; y <= 3; y++) {
      for (let z = 0; z <= 3; z++) {
        const atom = new THREE.Mesh(atomGeom, atomMat);
        atom.position.copy(localPoint(x, y, z));
        atom.userData.lattice = { x, y, z };
        atoms.add(atom);
        atomMeshes.push(atom);
      }
    }
  }

  if (kind === '100') {
    const p = makePlaneMesh(clippedPlanePolygon(new THREE.Vector3(0, 0, 1), 1), planeMat100);
    if (p) {
      planes.add(p);
      registerInteractive(p, {
        title: '{100} plane',
        tooltip: '{100}: one face-parallel square layer',
        body: 'The left panel shows a square plane parallel to a cube face. It cuts the cubic lattice at one constant z layer.'
      });
    }
  } else {
    for (const c of [-2, -1, 0, 1, 2]) {
      const p = makePlaneMesh(clippedPlanePolygon(new THREE.Vector3(1, 0, -1), c), planeMat110);
      if (p) {
        planes.add(p);
        registerInteractive(p, {
          title: '{110} plane family',
          tooltip: '{110}: parallel diagonal planes',
          body: 'The right panel shows several parallel diagonal {110} sheets through the same cubic lattice, as in the source figure.'
        });
      }
    }
  }

  return { kind, root, planes, rods, atoms, overlay, atomMeshes };
}

const panel100 = buildPanel('100', leftOrigin);
const panel110 = buildPanel('110', rightOrigin);
const panels = [panel100, panel110];

setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 45,
  depthScale: 0.5,
  heightFraction: 0.70,
  target: [0, 0, 0],
  distanceScale: 1.4
});

scene.updateMatrixWorld(true);

function worldFromPanel(panel, x, y, z) {
  const p = localPoint(x, y, z);
  panel.root.localToWorld(p);
  return p;
}

const labelEntries = [
  addLabel('{100}', worldFromPanel(panel100, 1.5, 3.35, 1), { fontSize: '13px', bold: true, color: '#14555a', background: 'rgba(255,255,255,0.75)' }),
  addLabel('{110}', worldFromPanel(panel110, 1.7, 3.35, 1.4), { fontSize: '13px', bold: true, color: '#14555a', background: 'rgba(255,255,255,0.75)' }),
  addLabel('d<sub>100</sub> = a', worldFromPanel(panel100, 3.45, 2.42, 1.5), { fontSize: '12px', bold: true, color: '#14555a', background: 'rgba(255,255,255,0.75)' }),
  addLabel('d<sub>110</sub> = a/√2', worldFromPanel(panel110, 3.30, 2.42, 0.65), { fontSize: '12px', bold: true, color: '#14555a', background: 'rgba(255,255,255,0.75)' })
];

function setLabelsVisible(v) {
  for (const e of labelEntries) e.div.style.visibility = v ? 'visible' : 'hidden';
}

function rebuildTeachingOverlay(panel) {
  clearGroup(panel.overlay);
  for (const atom of panel.atomMeshes) atom.material = atomMat;
  if (faithfulEl.checked) return;

  const layer = Number(layerEl.value);
  const haloGeom = new THREE.SphereGeometry(0.072, 18, 12);

  if (panel.kind === '100') {
    const c = Math.min(3, Math.max(0, layer));
    const selectedPlane = makePlaneMesh(clippedPlanePolygon(new THREE.Vector3(0, 0, 1), c), activePlaneMat);
    if (selectedPlane) panel.overlay.add(selectedPlane);
    for (const atom of panel.atomMeshes) {
      const q = atom.userData.lattice;
      if (Math.abs(q.z - c) < 0.02) {
        atom.material = atomHiMat;
        const halo = new THREE.Mesh(haloGeom, haloMat);
        halo.position.copy(atom.position);
        panel.overlay.add(halo);
      }
    }
    makeArrow(panel.overlay, new THREE.Vector3(3.35, 2.35, c), new THREE.Vector3(3.35, 2.35, Math.min(3, c + 1)));
  } else {
    const constants = [-2, -1, 0, 1, 2];
    const c = constants[layer] ?? 0;
    const selectedPlane = makePlaneMesh(clippedPlanePolygon(new THREE.Vector3(1, 0, -1), c), activePlaneMat);
    if (selectedPlane) panel.overlay.add(selectedPlane);
    for (const atom of panel.atomMeshes) {
      const q = atom.userData.lattice;
      if (Math.abs((q.x - q.z) - c) < 0.02) {
        atom.material = atomHiMat;
        const halo = new THREE.Mesh(haloGeom, haloMat);
        halo.position.copy(atom.position);
        panel.overlay.add(halo);
      }
    }
    const startZ = 1.4;
    const startX = Math.min(3, Math.max(0, c + startZ));
    makeArrow(panel.overlay, new THREE.Vector3(startX, 2.35, startZ), new THREE.Vector3(startX + 0.5, 2.35, startZ - 0.5));
  }
}

function updateAppearance() {
  const op = Number(opacityEl.value) / 100;
  opacityValueEl.textContent = Math.round(op * 100) + '%';
  layerValueEl.textContent = layerEl.value;

  planeMat100.opacity = Math.min(0.60, op + 0.06);
  planeMat110.opacity = op;
  activePlaneMat.opacity = Math.min(0.62, op + 0.14);

  const mode = panelModeEl.value;
  panel100.root.visible = mode === 'both' || mode === '100';
  panel110.root.visible = mode === 'both' || mode === '110';

  const teaching = !faithfulEl.checked;
  setLabelsVisible(teaching);

  for (const p of panels) rebuildTeachingOverlay(p);

  if (faithfulEl.checked) {
    stepTitleEl.textContent = mode === '110' ? 'Source view: {110}' : mode === '100' ? 'Source view: {100}' : 'Source view: comparison';
    stepNarrationEl.textContent = 'Extra labels, halos, arrows, and highlighted effects are hidden so the display stays close to the two-panel source figure.';
  }
}

panelModeEl.addEventListener('change', updateAppearance);
faithfulEl.addEventListener('change', updateAppearance);
opacityEl.addEventListener('input', updateAppearance);
layerEl.addEventListener('input', updateAppearance);

const demoSteps = [
  {
    title: 'Compare {100} and {110}',
    narration: 'Both panels use the same cubic lattice. The left panel contains a face-parallel square {100} sheet; the right panel contains several diagonal {110} sheets.',
    mode: 'both',
    faithful: true,
    layer: 2
  },
  {
    title: 'Teaching overlay: {100}',
    narration: 'The {100} plane is parallel to a cube face. Turning off source-faithful display reveals the selected layer, its atoms, and the spacing direction.',
    mode: '100',
    faithful: false,
    layer: 1
  },
  {
    title: 'Source-faithful {110} planes',
    narration: 'The right panel keeps the multiple pale teal diagonal planes visible at once, matching the source composition instead of showing only one active plane.',
    mode: '110',
    faithful: true,
    layer: 2
  },
  {
    title: 'Teaching overlay: {110}',
    narration: 'For {110}, neighboring planes are diagonal and closer together: d110 = a/√2. The overlay marks one chosen sheet without replacing the full plane family.',
    mode: '110',
    faithful: false,
    layer: 2
  }
];

let currentStep = 0;
let playTimer = null;

function goToStep(i) {
  currentStep = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  panelModeEl.value = step.mode;
  faithfulEl.checked = step.faithful;
  layerEl.value = step.layer;
  stepTitleEl.textContent = step.title;
  stepNarrationEl.textContent = step.narration;
  updateAppearance();
}

document.getElementById('prevStep').addEventListener('click', () => {
  if (playTimer) {
    clearInterval(playTimer);
    playTimer = null;
    document.getElementById('playDemo').textContent = 'Play';
  }
  goToStep(currentStep - 1);
});

document.getElementById('nextStep').addEventListener('click', () => {
  if (playTimer) {
    clearInterval(playTimer);
    playTimer = null;
    document.getElementById('playDemo').textContent = 'Play';
  }
  goToStep(currentStep + 1);
});

document.getElementById('playDemo').addEventListener('click', (e) => {
  if (playTimer) {
    clearInterval(playTimer);
    playTimer = null;
    e.currentTarget.textContent = 'Play';
    return;
  }
  e.currentTarget.textContent = 'Pause';
  goToStep(currentStep);
  playTimer = setInterval(() => goToStep(currentStep + 1), 2400);
});

updateAppearance();
